<?php if ( ! defined( 'ABSPATH' ) ) { exit; } $thread_id = isset( $args['thread_id'] ) ? absint( $args['thread_id'] ) : 0; ?><form id="sd-message-compose" class="sd-message-compose" data-sd-message-form data-thread-id="<?php echo esc_attr( $thread_id ); ?>"><h2><?php echo $thread_id ? esc_html__( 'Reply', 'social-discovery' ) : esc_html__( 'New message', 'social-discovery' ); ?></h2><?php if ( ! $thread_id ) : ?><label><?php esc_html_e( 'Recipient user ID', 'social-discovery' ); ?><input type="number" min="1" name="recipient_id" required></label><label><?php esc_html_e( 'Subject', 'social-discovery' ); ?><input type="text" name="subject" maxlength="120"></label><?php endif; ?><label><?php esc_html_e( 'Message', 'social-discovery' ); ?><textarea name="content" rows="5" maxlength="2000" required></textarea></label><p class="sd-form-feedback" data-sd-message-feedback aria-live="polite"></p><button class="sd-button" type="submit"><?php esc_html_e( 'Send message', 'social-discovery' ); ?></button></form>
